css:
.metaverselab-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #0a0a2e 0%, #1a1a4e 50%, #0d0d3b 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    color: #e0e0e0;
}

.metaverselab-sim-header {
    background: linear-gradient(135deg, #6c3ce0 0%, #00d4ff 100%);
    color: white;
    padding: 30px;
    border-radius: 20px;
    margin-bottom: 30px;
    box-shadow: 0 8px 32px rgba(108, 60, 224, 0.35);
    text-align: center;
}

.metaverselab-sim-header h1 {
    font-size: 1.7rem;
    margin-bottom: 5px;
}

.metaverselab-sim-header p {
    margin: 0;
    opacity: 0.9;
    font-size: 1rem;
}

.metaverselab-sim-period-counter {
    text-align: center;
    font-size: 1.1rem;
    margin-bottom: 25px;
    color: #00d4ff;
    font-weight: 600;
}

.metaverselab-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 20px;
    margin-bottom: 30px;
}

.metaverselab-sim-status-card {
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 15px;
    padding: 25px 20px;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.25);
    transition: transform 0.3s ease;
    text-align: center;
    backdrop-filter: blur(10px);
}

.metaverselab-sim-status-card:hover {
    transform: translateY(-5px);
}

.metaverselab-card-accuracy {
    border-top: 3px solid #00d4ff;
}

.metaverselab-card-cases {
    border-top: 3px solid #6c3ce0;
}

.metaverselab-card-quadrant {
    border-top: 3px solid #ff6b9d;
}

.metaverselab-card-grade {
    border-top: 3px solid #00e676;
}

.metaverselab-sim-label {
    color: #999;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 8px;
}

.metaverselab-sim-value {
    font-size: 1.8rem;
    font-weight: 700;
    color: #fff;
}

.metaverselab-sim-quadrant-text {
    font-size: 0.95rem;
    line-height: 1.3;
}

.metaverselab-sim-briefing {
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(108, 60, 224, 0.3);
    border-radius: 15px;
    padding: 25px;
    margin-bottom: 30px;
}

.metaverselab-sim-briefing h3 {
    color: #00d4ff;
    margin-bottom: 15px;
    font-size: 1.1rem;
}

.metaverselab-sim-briefing-text {
    font-size: 0.93rem;
    line-height: 1.7;
    color: #ccc;
}

.metaverselab-sim-controls {
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 15px;
    padding: 25px;
    margin-bottom: 30px;
}

.metaverselab-sim-controls h3 {
    color: #00d4ff;
    margin-bottom: 20px;
    font-size: 1.1rem;
}

.metaverselab-sim-slider-group {
    margin-bottom: 18px;
}

.metaverselab-sim-slider-group label {
    display: block;
    font-size: 0.9rem;
    margin-bottom: 6px;
    color: #bbb;
    font-weight: 600;
}

.metaverselab-sim-slider-row {
    display: flex;
    align-items: center;
    gap: 12px;
}

.metaverselab-sim-range {
    flex: 1;
    -webkit-appearance: none;
    appearance: none;
    height: 8px;
    border-radius: 4px;
    background: rgba(255, 255, 255, 0.15);
    outline: none;
}

.metaverselab-sim-range::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 22px;
    height: 22px;
    border-radius: 50%;
    background: linear-gradient(135deg, #6c3ce0, #00d4ff);
    cursor: pointer;
    box-shadow: 0 2px 8px rgba(108, 60, 224, 0.4);
}

.metaverselab-sim-range::-moz-range-thumb {
    width: 22px;
    height: 22px;
    border-radius: 50%;
    background: linear-gradient(135deg, #6c3ce0, #00d4ff);
    cursor: pointer;
    border: none;
}

.metaverselab-sim-range-val {
    min-width: 32px;
    text-align: center;
    font-weight: 700;
    font-size: 1.1rem;
    color: #00d4ff;
    background: rgba(0, 212, 255, 0.1);
    border-radius: 8px;
    padding: 4px 8px;
}

.metaverselab-sim-btn-row {
    display: flex;
    gap: 10px;
    margin-top: 22px;
    flex-wrap: wrap;
}

.metaverselab-sim-container .btn-primary {
    background: linear-gradient(135deg, #6c3ce0 0%, #00d4ff 100%);
    border: none;
    padding: 12px 30px;
    border-radius: 10px;
    font-weight: 600;
    font-size: 1rem;
    color: #fff;
}

.metaverselab-sim-container .btn-primary:hover {
    opacity: 0.9;
    transform: translateY(-2px);
}

.metaverselab-sim-container .btn-outline-secondary {
    border-color: rgba(255, 255, 255, 0.3);
    color: #ccc;
}

.metaverselab-sim-history {
    margin-bottom: 30px;
}

.metaverselab-sim-container .table {
    color: #ddd;
    background: rgba(255, 255, 255, 0.03);
    border-radius: 10px;
    overflow: hidden;
}

.metaverselab-sim-container .table th {
    background: rgba(108, 60, 224, 0.2);
    border-color: rgba(255, 255, 255, 0.1);
    color: #00d4ff;
    font-size: 0.78rem;
    text-transform: uppercase;
}

.metaverselab-sim-container .table td {
    border-color: rgba(255, 255, 255, 0.05);
    font-size: 0.88rem;
}

.metaverselab-sim-chart {
    background: rgba(255, 255, 255, 0.05);
    border-radius: 15px;
    padding: 20px;
    height: 340px;
}

@media (max-width: 768px) {
    .metaverselab-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .metaverselab-sim-header h1 {
        font-size: 1.3rem;
    }
    .metaverselab-sim-value {
        font-size: 1.4rem;
    }
}

