        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalAccuracy: 0,
                    casesEvaluated: 0,
                    accuracyHistory: [],
                    caseNames: [],
                    studentScores: [],
                    expertScores: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    tech: 5,
                    biz: 5,
                    adoption: 5,
                    roi: 5,
                    moat: 5
                };
            }
            this._setupSliderListeners();
            this._updateBriefing(state);
        }

        _isSpanish() {
            var lang = 'en';
            try {
                lang = ((window.mySimulation && window.mySimulation.config && window.mySimulation.config.language) ||
                        (document.documentElement && document.documentElement.getAttribute('lang')) || 'en').toLowerCase();
            } catch (e) {}
            return lang.indexOf('es') === 0;
        }

        _localizeCaseName(name, es) {
            if (!es) return name;
            for (var i = 0; i < this.ROUNDS.length; i++) {
                if (this.ROUNDS[i].caseName === name) return this.ROUNDS[i].caseNameEs || name;
            }
            return name;
        }

        _setupSliderListeners() {
            var sliders = [
                { id: 'techMaturityInput', valId: 'techMaturityVal' },
                { id: 'businessModelInput', valId: 'businessModelVal' },
                { id: 'userAdoptionInput', valId: 'userAdoptionVal' },
                { id: 'roiPotentialInput', valId: 'roiPotentialVal' },
                { id: 'competitiveMoatInput', valId: 'competitiveMoatVal' }
            ];
            sliders.forEach(function(s) {
                var slider = document.getElementById(s.id);
                var valEl = document.getElementById(s.valId);
                if (slider && valEl) {
                    slider.addEventListener('input', function() {
                        valEl.textContent = slider.value;
                    });
                }
            });
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var __es = this._isSpanish();

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = (__es && round.descriptionEs) ? round.descriptionEs : round.description;

            var contEl = document.getElementById('continuumDisplay');
            if (contEl) contEl.textContent = (__es && round.continuumEs) ? round.continuumEs : round.continuum;

            var sliderIds = ['techMaturityInput', 'businessModelInput', 'userAdoptionInput', 'roiPotentialInput', 'competitiveMoatInput'];
            var valIds = ['techMaturityVal', 'businessModelVal', 'userAdoptionVal', 'roiPotentialVal', 'competitiveMoatVal'];
            sliderIds.forEach(function(id, i) {
                var sl = document.getElementById(id);
                var vl = document.getElementById(valIds[i]);
                if (sl) { sl.value = 5; }
                if (vl) { vl.textContent = '5'; }
            });
        }

        validateDecisions(decisions) {
            // v1.1.0 FIX: do NOT call _updateBriefing() here. It reset every slider to 5
            // BEFORE their values were read below, so each submission was scored as
            // 5/5/5/5/5 and the student's actual assessment was discarded. Read the live
            // slider values directly; the next round's briefing/reset is handled after
            // calculateResults().
            var techInput = document.getElementById('techMaturityInput');
            var bizInput = document.getElementById('businessModelInput');
            var adoptionInput = document.getElementById('userAdoptionInput');
            var roiInput = document.getElementById('roiPotentialInput');
            var moatInput = document.getElementById('competitiveMoatInput');

            if (techInput) decisions.tech = parseInt(techInput.value);
            if (bizInput) decisions.biz = parseInt(bizInput.value);
            if (adoptionInput) decisions.adoption = parseInt(adoptionInput.value);
            if (roiInput) decisions.roi = parseInt(roiInput.value);
            if (moatInput) decisions.moat = parseInt(moatInput.value);

            if (decisions.tech < 1 || decisions.tech > 10 || decisions.biz < 1 || decisions.biz > 10 || decisions.adoption < 1 || decisions.adoption > 10 || decisions.roi < 1 || decisions.roi > 10 || decisions.moat < 1 || decisions.moat > 10) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('score_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var expert = round.expert;

            var devTech = Math.abs(d.tech - expert.tech);
            var devBiz = Math.abs(d.biz - expert.biz);
            var devAdoption = Math.abs(d.adoption - expert.adoption);
            var devRoi = Math.abs(d.roi - expert.roi);
            var devMoat = Math.abs(d.moat - expert.moat);

            var avgDeviation = (devTech + devBiz + devAdoption + devRoi + devMoat) / 5;
            // v1.2.0 scoring: each axis earns 1 - gap/9 as before, but where the panel is clear-cut
            // (a strength at 8 or more, a weakness at 3 or less) the analyst must make the same call
            // (7 or more, 4 or less). A hedge at 5-6 keeps a third of the credit, the opposite call none.
            // Without this, sliders left at the midpoint scored above nine in ten random players.
            var hedges = 0, misses = 0, credit = 0;
            ['tech', 'biz', 'adoption', 'roi', 'moat'].forEach(function(k) {
                var s = d[k], e = expert[k];
                var c = Math.max(0, 1 - Math.abs(s - e) / 9);
                if (e >= 8 || e <= 3) {
                    var same = e >= 8 ? s >= 7 : s <= 4;
                    var opposite = e >= 8 ? s <= 4 : s >= 7;
                    if (opposite) { c = 0; misses++; }
                    else if (!same) { c = c / 3; hedges++; }
                }
                credit += c;
            });
            var accuracy = Math.round(Math.max(0, credit / 5 * 100));

            // v1.1.0 undo-idempotency guard. Cumulative domainState below would
            // double-count if the student used Undo and re-submitted a period. Snapshot the
            // mutable state entering each period; if we detect a re-submit of an earlier
            // period (a snapshot exists and _snapshotPeriod is beyond the current period),
            // roll domainState back to that period's entry state before recomputing.
            var __ds = state.domainState;
            var __cp = state.currentPeriod || 1;
            __ds._periodSnapshots = __ds._periodSnapshots || {};
            if (__ds._periodSnapshots[__cp] && typeof __ds._snapshotPeriod === 'number' && __ds._snapshotPeriod > __cp) {
                var __restore = __ds._periodSnapshots[__cp];
                Object.keys(__restore).forEach(function(k) { __ds[k] = JSON.parse(JSON.stringify(__restore[k])); });
                Object.keys(__ds._periodSnapshots).forEach(function(k) { if (+k > __cp) delete __ds._periodSnapshots[k]; });
            }
            __ds._periodSnapshots[__cp] = {
                totalAccuracy: __ds.totalAccuracy,
                casesEvaluated: __ds.casesEvaluated,
                accuracyHistory: JSON.parse(JSON.stringify(__ds.accuracyHistory)),
                caseNames: JSON.parse(JSON.stringify(__ds.caseNames)),
                studentScores: JSON.parse(JSON.stringify(__ds.studentScores)),
                expertScores: JSON.parse(JSON.stringify(__ds.expertScores))
            };
            __ds._snapshotPeriod = __cp;

            state.domainState.casesEvaluated += 1;
            state.domainState.accuracyHistory.push(accuracy);
            state.domainState.caseNames.push(round.caseName);

            var totalAcc = state.domainState.accuracyHistory.reduce(function(s, v) { return s + v; }, 0);
            state.domainState.totalAccuracy = Math.round(totalAcc / state.domainState.accuracyHistory.length);

            // v1.1.0 FIX: persist the gradebook composite every period. The server reads
            // domainState.performance.overallScore for grading; when absent it coerced the
            // grade to 0.0/100 for every student. Composite = running mean assessment
            // accuracy (0-100), i.e. the score the sim already shows the learner.
            state.domainState.performance = state.domainState.performance || {};
            state.domainState.performance.overallScore = state.domainState.totalAccuracy;
            state.domainState.performance.score = state.domainState.totalAccuracy;
            state.domainState.performance.grade = (state.domainState.totalAccuracy >= 85) ? 'A'
                : (state.domainState.totalAccuracy >= 70) ? 'B'
                : (state.domainState.totalAccuracy >= 55) ? 'C'
                : (state.domainState.totalAccuracy > 0) ? 'D' : 'F';

            state.domainState.studentScores.push({
                tech: d.tech, biz: d.biz, adoption: d.adoption, roi: d.roi, moat: d.moat
            });
            state.domainState.expertScores.push({
                tech: expert.tech, biz: expert.biz, adoption: expert.adoption, roi: expert.roi, moat: expert.moat
            });

            var studentAvg = ((d.tech + d.biz + d.adoption + d.roi + d.moat) / 5).toFixed(1);
            var expertAvg = ((expert.tech + expert.biz + expert.adoption + expert.roi + expert.moat) / 5).toFixed(1);

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            return {
                period: state.currentPeriod,
                caseName: round.caseName,
                studentAvg: parseFloat(studentAvg),
                expertAvg: parseFloat(expertAvg),
                accuracy: accuracy,
                totalAccuracy: state.domainState.totalAccuracy,
                devTech: devTech,
                devBiz: devBiz,
                devAdoption: devAdoption,
                devRoi: devRoi,
                devMoat: devMoat,
                hedges: hedges,
                misses: misses
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('accuracyDisplay', 'domainState.totalAccuracy',
                function(v) { return v > 0 ? v + '%' : '--'; });
            uiManager.bind('casesDisplay', 'domainState.casesEvaluated');
            uiManager.bind('gradeDisplay', 'domainState.totalAccuracy',
                function(v) {
                    if (v >= 85) return 'A';
                    if (v >= 70) return 'B';
                    if (v >= 55) return 'C';
                    if (v > 0) return 'D';
                    return '--';
                });
        }

