        getPerformanceSummary(history) {
            if (!history.length) return {};
            var accuracies = history.map(function(r) { return r.results ? r.results.accuracy || 0 : 0; });
            var avgAccuracy = Math.round(accuracies.reduce(function(s, v) { return s + v; }, 0) / accuracies.length);

            var bestCase = '';
            var worstCase = '';
            var bestAcc = 0;
            var worstAcc = 100;
            history.forEach(function(r) {
                if (r.results && r.results.accuracy >= bestAcc) {
                    bestAcc = r.results.accuracy;
                    bestCase = r.results.caseName || '';
                }
                if (r.results && r.results.accuracy <= worstAcc) {
                    worstAcc = r.results.accuracy;
                    worstCase = r.results.caseName || '';
                }
            });

            var performance = 'Novice Analyst';
            if (avgAccuracy >= 85) performance = 'Expert Strategy Analyst';
            else if (avgAccuracy >= 70) performance = 'Proficient Analyst';
            else if (avgAccuracy >= 55) performance = 'Developing Analyst';

            var __es = this._isSpanish();
            var __wc = this._localizeCaseName(worstCase, __es);
            var insights = [];
            if (avgAccuracy >= 85) {
                if (__es) {
                    insights.push('Capacidad sobresaliente para separar el hype del valor de negocio real en las tecnologías inmersivas.');
                    insights.push('Tus evaluaciones coinciden estrechamente con los benchmarks expertos en madurez tecnológica y análisis de ROI.');
                } else {
                    insights.push('Outstanding ability to separate hype from real business value across immersive technologies.');
                    insights.push('Your assessments closely match expert benchmarks on technology maturity and ROI analysis.');
                }
            } else if (avgAccuracy >= 70) {
                if (__es) {
                    insights.push('Juicio analítico sólido con margen de refinamiento en categorías específicas de casos de uso.');
                    insights.push('Revisa tu caso con menor puntuación (' + __wc + ') para identificar puntos ciegos de tu evaluación.');
                } else {
                    insights.push('Solid analytical judgment with room for refinement in specific use case categories.');
                    insights.push('Review your lowest-scoring case (' + __wc + ') to identify assessment blind spots.');
                }
            } else if (avgAccuracy >= 55) {
                if (__es) {
                    insights.push('Muestras una comprensión básica pero podrías estar sobrevalorando el hype mediático en tus evaluaciones.');
                    insights.push('Enfócate en métricas duras (retorno de ROI, tamaño de la base de usuarios, costos de cambio) en lugar de la novedad tecnológica.');
                } else {
                    insights.push('You show basic understanding but may be over-weighting media hype in your assessments.');
                    insights.push('Focus on hard metrics (ROI payback, user base size, switching costs) rather than technology novelty.');
                }
            } else {
                if (__es) {
                    insights.push('Tus evaluaciones divergieron significativamente de los benchmarks expertos. Considera si el hype influyó en tu puntuación.');
                    insights.push('El marco del Gartner Hype Cycle puede ayudarte a calibrar las evaluaciones de madurez tecnológica.');
                } else {
                    insights.push('Your assessments diverged significantly from expert benchmarks. Consider whether hype influenced your scoring.');
                    insights.push('The Gartner Hype Cycle framework can help calibrate technology maturity assessments.');
                }
            }

            return {
                avgAccuracy: avgAccuracy,
                totalPeriods: history.length,
                bestCase: bestCase,
                bestAccuracy: bestAcc,
                worstCase: worstCase,
                worstAccuracy: worstAcc,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var es = this._isSpanish();
            var tiersEs = {
                'Novice Analyst': 'Analista Novato',
                'Developing Analyst': 'Analista en Desarrollo',
                'Proficient Analyst': 'Analista Competente',
                'Expert Strategy Analyst': 'Analista Estratégico Experto'
            };
            var perf = es ? (tiersEs[summary.performance] || summary.performance || '') : (summary.performance || '');
            var acc = (summary.avgAccuracy != null) ? summary.avgAccuracy : 0;
            var bestC = this._localizeCaseName(summary.bestCase || '', es);
            var worstC = this._localizeCaseName(summary.worstCase || '', es);
            function esc(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
            var L = es
                ? { title:'\u00a1Evaluación completada!', perf:'Nivel de analista', best:'Mejor caso', worst:'Caso más débil', takeaways:'Conclusiones clave' }
                : { title:'Assessment complete!', perf:'Analyst level', best:'Best case', worst:'Weakest case', takeaways:'Key takeaways' };
            var html = '<div class="metaverselab-complete" style="text-align:center;">';
            html += '<h3 style="margin-bottom:8px;">' + L.title + '</h3>';
            html += '<p style="font-size:2rem;font-weight:700;margin:6px 0;">' + acc + '%</p>';
            html += '<p style="margin:2px 0;"><strong>' + L.perf + ':</strong> ' + esc(perf) + '</p>';
            if (bestC)  html += '<p style="margin:2px 0;">' + L.best + ': ' + esc(bestC) + ' (' + (summary.bestAccuracy || 0) + '%)</p>';
            if (worstC) html += '<p style="margin:2px 0;">' + L.worst + ': ' + esc(worstC) + ' (' + (summary.worstAccuracy || 0) + '%)</p>';
            if (summary.insights && summary.insights.length) {
                html += '<hr style="margin:12px 0;opacity:.3;"><p><strong>' + L.takeaways + '</strong></p>';
                html += '<ul style="text-align:left;max-width:560px;margin:0 auto;">';
                for (var i = 0; i < summary.insights.length; i++) { html += '<li>' + esc(summary.insights[i]) + '</li>'; }
                html += '</ul>';
            }
            html += '</div>';
            return html;
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.accuracy >= 85) return window.mySimulation.t('hint_excellent');
            if ((results.hedges || 0) >= 2) return window.mySimulation.t('hint_hedge');
            if (results.accuracy >= 65) return window.mySimulation.t('hint_good');
            if (results.accuracy >= 45) return window.mySimulation.t('hint_review');
            return window.mySimulation.t('hint_hype');
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.caseName', label: 'Use Case', i18nKey: 'col_case' },
                { key: 'results.studentAvg', label: 'Your Avg', i18nKey: 'col_student_avg', formatter: function(v) { return v.toFixed(1); } },
                { key: 'results.expertAvg', label: 'Expert Avg', i18nKey: 'col_expert_avg', formatter: function(v) { return v.toFixed(1); } },
                { key: 'results.accuracy', label: 'Accuracy', i18nKey: 'col_accuracy', formatter: function(v) { return v + '%'; } }
            ];
        }

        getPresets() { return null; }

